package org.eclipse.rdf4j.sail.lmdb;

import java.util.function.BooleanSupplier;

/**
 * Drives the applier loop. The production implementation runs the loop on one dedicated thread; tests run it one unit
 * at a time. The loop body returns whether it did any work; a scheduler keeps calling it while it does and parks until
 * {@link #wake()} otherwise.
 */
interface ApplierScheduler {

	/** Installs the loop body. Called once, before any {@link #wake()}. */
	void start(BooleanSupplier runOne);

	/** Signals that the loop may have work; safe from any thread. */
	void wake();

	/** Runs a task after a delay; the task itself only enqueues applier work and wakes the loop. */
	void schedule(Runnable task, long delayMillis);

	void shutdown();
}
